  const attendance: AttendanceRecord[] = [];
  const memByUser = new Map(memberships.map((m) => [m.userId, m]));

  const record = (uid: string, date: ISODate, start: string, end: string, paidHours?: number) => {
    const m = memByUser.get(uid)!;
    const h = hash(uid + date) % 100;
    const startMin = hmToMinutes(start);
    const endMin = hmToMinutes(end);
    if (date === today) {
      if (uid === 'u_bat') return; // Bat clocks in live during the demo
      if (nowMin < startMin - 5) return;
    }
    const base = {
      id: `at_${uid}_${date}`,
      membershipId: m.id,
      userId: uid,
      companyId: m.companyId,
      branchId: m.branchId ?? 'b_nk_center',
      date,
    };
    if (h < 3 && date !== today) {
      attendance.push({ ...base, hours: 0, status: 'absent', lateMinutes: 0 });
      return;
    }
    const late = h < 12;
    const inMin = late ? startMin + 6 + (h % 20) : startMin - (h % 5);
    const finished = date !== today || nowMin >= endMin;
    const outMin = endMin + (h % 4);
    const worked = finished ? (paidHours ?? (outMin - inMin) / 60) : 0;
    attendance.push({
      ...base,
      clockIn: minutesToHM(inMin),
      clockOut: finished ? minutesToHM(outMin) : undefined,
      hours: Math.round(worked * 10) / 10,
      status: late ? 'late' : 'on_time',
      lateMinutes: late ? inMin - startMin : 0,
    });
  };

