    historySnapshots,
    payouts,
    payslips,
    payrollSettings: [{ companyId: 'c_narlag', withdrawCapPercent: 50, paydayRule: 'Сар бүрийн 5' }],
    taxConfig: { incomeTaxPercent: 10, socialInsuranceEmployeePercent: 11.5, effectiveFrom: '2026-01-01' },
    announcements,
